D=/workspace/nox/c300_voice/voice2; V=/workspace/nox/voice2_venv
echo  | base64 -d > $D/ru_norm.py
echo  | base64 -d > $D/tts2_server.py
pkill -f "tts2_server.py"; pkill -f test10.py; sleep 1
cd $D; export NOX_VOICE_MODELS=/workspace/nox/voice_models
nohup setsid nice -n 5 $V/bin/python tts2_server.py > /workspace/nox/svc/logs/tts2.log 2>&1 &
cat /workspace/nox/svc/start_extra.sh | cut -c1-200 | head -20
SE=/workspace/nox/svc/start_extra.sh
grep -q tts2_server $SE || { cp $SE $SE.bak_b_1; printf '%s\n' '(echo > /dev/tcp/127.0.0.1/8095) 2>/dev/null || { cd /workspace/nox/c300_voice/voice2 && NOX_VOICE_MODELS=/workspace/nox/voice_models nohup setsid nice -n 5 /workspace/nox/voice2_venv/bin/python tts2_server.py >/workspace/nox/svc/logs/tts2.log 2>&1 & }' >> $SE; }
R=/workspace/nox/web/pkg/server/svc_registry.json
[ -f $R.bak_b_1 ] || cp $R $R.bak_b_1
python3 - <<'PY'
import json
R="/workspace/nox/web/pkg/server/svc_registry.json"
d=json.load(open(R))
d["tts2"]={"port":8095,"mode":"strip","title":"TTS2 Silero","ui":False,"note":"Озвучка v5 ru: нормализация, ударения, паузы. POST /svc/tts2/synth"}
json.dump(d,open(R,"w"),ensure_ascii=False,indent=2)
print("reg ok")
PY
echo "== proxy"; ls /workspace/nox/web/pkg/server | head -20; grep -n "registry\|svc_registry" /workspace/nox/web/pkg/server/svc_proxy.py | head -10
sleep 30
curl -s http://127.0.0.1:8091/svc/tts2/health | head -c 300; echo
curl -s -X POST http://127.0.0.1:8091/svc/tts2/prep -H 'Content-Type: application/json' -d '{"text":"Мы были в 1996 году, 85% и 48 ГБ."}' | head -c 600
